<?php// Start output buffering to prevent any accidental outputob_start();// Set error reportingerror_reporting(E_ALL);ini_set('display_errors', 0);session_start();// Clear any previous outputob_clean();require_once __DIR__ . '/access.php';header('Content-Type: application/json; charset=UTF-8');mb_internal_encoding('UTF-8');// Check if user has permissionif (!isAdmin() && !isManager()) {    http_response_code(403);    echo json_encode(['success' => false, 'message' => 'Nemáte oprávnění k této akci']);    exit;}if ($_SERVER['REQUEST_METHOD'] !== 'POST') {    echo json_encode(['success' => false, 'message' => 'Neplatná metoda požadavku']);    exit;}// Get JSON input$input = file_get_contents('php://input');$data = json_decode($input, true);if (!$data || !isset($data['folder']) || !isset($data['order'])) {    echo json_encode(['success' => false, 'message' => 'Chybí požadovaná data']);    exit;}$folderName = $data['folder'];$fileOrder = $data['order'];// Sanitize folder name$folderName = basename($folderName);// Validate folder exists$baseDir = getRoot('videos');$folderPath = $baseDir . $folderName . '/';if (!is_dir($folderPath)) {    echo json_encode(['success' => false, 'message' => 'Složka nenalezena']);    exit;}// Validate that all files in order actually existforeach ($fileOrder as $fileName) {    $filePath = $folderPath . basename($fileName);    if (!file_exists($filePath)) {        echo json_encode(['success' => false, 'message' => 'Soubor nenalezen: ' . $fileName]);        exit;    }}// Save order to JSON file$orderFile = $folderPath . '.order.json';$orderData = [    'folder' => $folderName,    'order' => $fileOrder,    'updated' => date('Y-m-d H:i:s')];if (file_put_contents($orderFile, json_encode($orderData, JSON_PRETTY_PRINT))) {    echo json_encode(['success' => true, 'message' => 'Pořadí bylo uloženo']);} else {    echo json_encode(['success' => false, 'message' => 'Nepodařilo se uložit pořadí']);}exit;?>